static double real(CelestialBody &body,const QString &name){return body.GetRealParameter(body.GetParameterID(name.toStdString()));}
static QString textValue(CelestialBody &body,const QString &name){return QString::fromStdString(body.GetStringParameter(body.GetParameterID(name.toStdString())));}
static bool near(double a,double b){return std::abs(a-b)<=1e-12*std::max(1.,std::abs(b));}
static QString withoutMu(QString source,const QString &name){source.remove(QRegularExpression("^[ \\t]*(?:GMAT[ \\t]+)?"+QRegularExpression::escape(name)+"\\.Mu[ \\t]*=[^;\\n]+;[ \\t]*(?:\\n|$)",QRegularExpression::MultilineOption));return source;}
